async function visitLedger(stream, visitor) {
  const reader = stream.getReader();
  const decoder = new TextDecoder("utf-8");
  const parts = [];

  let accepted = 0;
  let rejected = 0;
  let line = 1;
  let normalCompletion = false;

  async function visitLine(rawLine) {
    if (rawLine.endsWith("\r")) {
      rawLine = rawLine.slice(0, -1);
    }

    if (rawLine.trim().length === 0) {
      return false;
    }

    let value;
    try {
      value = JSON.parse(rawLine);
    } catch {
      rejected++;
      return false;
    }

    accepted++;
    return (await visitor({ line, value })) === false;
  }

  async function consume(text) {
    let start = 0;

    while (true) {
      const end = text.indexOf("\n", start);
      if (end === -1) {
        break;
      }

      parts.push(text.slice(start, end));
      const rawLine = parts.join("");
      parts.length = 0;

      const stopped = await visitLine(rawLine);
      line++;

      if (stopped) {
        return true;
      }

      start = end + 1;
    }

    if (start < text.length) {
      parts.push(text.slice(start));
    }

    return false;
  }

  try {
    while (true) {
      const { done, value } = await reader.read();

      if (done) {
        const tail = decoder.decode();

        if (await consume(tail)) {
          return { accepted, rejected, stopped: true };
        }

        if (parts.length > 0) {
          const rawLine = parts.join("");
          parts.length = 0;

          if (await visitLine(rawLine)) {
            return { accepted, rejected, stopped: true };
          }
        }

        normalCompletion = true;
        return { accepted, rejected, stopped: false };
      }

      if (await consume(decoder.decode(value, { stream: true }))) {
        return { accepted, rejected, stopped: true };
      }
    }
  } finally {
    try {
      if (!normalCompletion) {
        await reader.cancel();
      }
    } finally {
      reader.releaseLock();
    }
  }
}
